# Evaluate detectors on the adversarial ELSA test set generated by the ensemble model

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
export PYTHONPATH="${SCRIPT_DIR}:${SCRIPT_DIR}/raid:${PYTHONPATH}"

# Available Models
# ojha2023, corvi2023, cavia2024, chen2024_convnext, chen2024_clip, koutlis2024, wang2020, effort, aide

# for model in cavia2024 chen2024_convnext chen2024_clip corvi2023 koutlis2024 ojha2023 wang2020; do

CKPT_DIR=/storageC/heddoubi/guard/external/checkpoints

declare -A CHECKPOINTS
CHECKPOINTS[effort]="${CKPT_DIR}/effort/genimage_sd14_released.pth"
CHECKPOINTS[aide]="${CKPT_DIR}/aide/genimage_sd14_released.pth"

for model in effort aide; do
  python raid/evaluate_detector.py \
  --model $model \
  --path-to-checkpoint "${CHECKPOINTS[$model]}" \
  --path_to_dataset /storageC/heddoubi/RAID/epsilon8 \
  --dataset_type subfolders \
  --output_dir output/evaluate_detector \
  --batch_size 50 \
  --num_workers 1 \
  --subset -1
done


